// ---------- PUBLIC HELPERS ----------

export function localizeCategory(cat: Category, lang: Lang): Category {
  const t = CATEGORIES[lang]?.[cat.slug];
  if (!t) return cat;
  return { ...cat, name: t.name, description: t.description };
}

export function localizeDestination(dest: Destination, lang: Lang): Destination {
  const t = DESTINATIONS[lang]?.[dest.slug];
  if (!t) return dest;
  return {
    ...dest,
    name: t.name,
    tagline: t.tagline,
    description: t.description,
    access: t.access,
    bestFor: t.bestFor,
  };
}

export function localizeActivity(act: Activity, lang: Lang): Activity {
  const t = ACTIVITIES[lang]?.[act.id];
  if (!t) {
    // No per-activity translation; still translate the duration and difficulty
    // fields generically so cards aren't a mix of languages.
    return {
      ...act,
      duration: translateDuration(act.duration, lang),
      difficulty: act.difficulty,
    };
  }
  return {
    ...act,
    title: t.title,
    description: t.description,
    highlights: t.highlights,
    duration: t.duration,
    category: t.category,
  };
}

export function difficultyLabel(d: Activity['difficulty'], lang: Lang): string {
  return DIFFICULTY[lang]?.[d] ?? d;
}
